payload.query:
query Jobs($departmentIds: [Int]
  $officeIds: [Int]
  $languages: [String]
  $roleTypes: [String]
  $searchQuery: String
) {
  jobs(departmentIds: $departmentIds
    officeIds: $officeIds
    languages: $languages
    roleTypes: $roleTypes
    searchQuery: $searchQuery
  ) {
    id
    title
    department {
      name
      id
    }
    office {
      id,
      location
    }
    location {
      name
    }
  }
}
